from pathlib import Path
p=Path(__file__).parent
lib=(p/'three.module.js').read_text(); data=(p/'scene.json').read_text()
html='''<!doctype html><html lang="tr"><meta charset="utf-8"><title>Aura • 3D Otopark</title><style>body{margin:0;background:#dce2e7;font:14px system-ui;color:#fff}#info{position:absolute;top:20px;left:20px;background:#152332e8;padding:20px;border-radius:12px;max-width:380px}h1{font-size:22px;margin:0 0 8px}p{line-height:1.5;margin:6px 0}button{border:0;border-radius:6px;margin:8px 5px 0 0;padding:9px;cursor:pointer}small{color:#b9c9d7}canvas{display:block}</style><div id="info"><h1>AURA FITNESS CLUB</h1><p>3D otopark yerleşimi · 3 bariyer</p><p>Sürükle: döndür · Tekerlek: yakınlaştır<br>Sağ tuşla sürükle: kaydır</p><button onclick="view('all')">Genel</button><button onclick="view('side')">Yan kapı</button><button onclick="view('main')">Giriş / çıkış</button><button onclick="view('top')">Üstten</button><p><small>Konsept model · Birim: metre<br>Şeritler yaklaşık 4 m; diğer ölçüler varsayımsal.<br>Araçlar, peyzaj ve ekipmanlar temsili.</small></p></div><script type="module">'''+lib+'\nconst items='+data+''';
const scene=new Scene();scene.background=new Color('#dce2e7');
const renderer=new WebGLRenderer({antialias:true});renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,2));document.body.appendChild(renderer.domElement);renderer.shadowMap.enabled=true;
const camera=new PerspectiveCamera(42,innerWidth/innerHeight,.1,600);
scene.add(new HemisphereLight(0xffffff,0x667070,2.4));const sun=new DirectionalLight(0xffffff,3);sun.position.set(-20,70,-20);scene.add(sun);
const mats={};const geo=new BoxGeometry(1,1,1);
for(const o of items){const mat=mats[o.color]??=new MeshStandardMaterial({color:o.color,roughness:.8});const m=new Mesh(geo,mat);m.name=o.name;m.position.set(...o.pos);m.scale.set(...o.size);m.rotation.y=o.rot;scene.add(m)}
let target=new Vector3(-22,0,17),r=Math.max(95,105/Math.max(.6,innerWidth/innerHeight)),theta=-.3,phi=.75;
function update(){camera.position.set(target.x+r*Math.sin(theta)*Math.sin(phi),target.y+r*Math.cos(phi),target.z-r*Math.cos(theta)*Math.sin(phi));camera.lookAt(target)}
window.view=(s)=>{if(s==='all'){target.set(-22,0,17);r=Math.max(95,105/Math.max(.6,innerWidth/innerHeight));theta=-.3;phi=.75}if(s==='side'){target.set(-3,0,5);r=24;theta=-.6;phi=.95}if(s==='main'){target.set(-32,0,2);r=24;theta=0;phi=1.02}if(s==='top'){target.set(-22,0,17);r=90;theta=0;phi=.01}update()};
let drag=null;renderer.domElement.oncontextmenu=e=>e.preventDefault();renderer.domElement.onpointerdown=e=>{drag={x:e.clientX,y:e.clientY,b:e.button};renderer.domElement.setPointerCapture(e.pointerId)};renderer.domElement.onpointerup=()=>drag=null;renderer.domElement.onpointermove=e=>{if(!drag)return;let dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(drag.b===2){target.x-=dx*r*.001;target.z-=dy*r*.001}else{theta-=dx*.006;phi=Math.max(.05,Math.min(1.5,phi+dy*.006))}drag.x=e.clientX;drag.y=e.clientY;update()};renderer.domElement.onwheel=e=>{e.preventDefault();r=Math.max(8,Math.min(180,r*Math.exp(e.deltaY*.001)));update()};onresize=()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)};update();renderer.setAnimationLoop(()=>renderer.render(scene,camera));
</script></html>'''
(p/'aura-3d-onizleme.html').write_text(html)
(p/'README.txt').write_text('AURA FITNESS CLUB — KONSEPT 3D MODEL\n\nGLB: renkli, ayrı adlandırılmış nesneler, metre birimi, Y yukarı.\nOBJ: geometrik aktarım alternatifi; renkler bu dosyada yoktur.\nHTML: internet gerektirmeyen 3D önizleme; tarayıcıda açın.\n\nBu model uydu görüntüsü ve onaylanan konseptten yaklaşık olarak oluşturuldu. Ölçülü saha/CAD projesi değildir. Her ana geçiş şeridi yaklaşık 4 m; bina, otopark ve kot ölçüleri varsayımsaldır. Bariyer, kapan ve kameralar temsili geometridir; üretici CAD modeli değildir.\n\nSoldaki yan geçiş sağdan sola; bariyer ön sınırda ve kapan geçişe dik. Ana kapı iki dış bariyerlidir, orta ada yoktur. Bina, araçlar ve ekipmanlar ayrı nesnelerdir.\n\nmodel_olustur.py geometri ve GLB/OBJ üretir. viewer_olustur.py çevrimdışı HTML üretir. Önizleme Three.js (MIT) kullanır.\n')
print('Offline viewer ready')
